#!/usr/bin/env python3\n\"\"\"\n统一分析引擎集成测试\n\n测试所有引擎模块的协作和集成功能\n\"\"\"\n\nimport unittest\nimport sys\nimport os\nfrom unittest.mock import Mock, patch\nimport pandas as pd\nimport datetime\n\n# 添加项目根目录到路径\nroot_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, root_dir)\n\nfrom analysis.engines.unified_indicator_engine import UnifiedIndicatorEngine\nfrom analysis.engines.shared_condition_evaluator import SharedConditionEvaluator\nfrom analysis.engines.complex_logic_processor import ComplexLogicProcessor\nfrom analysis.engines.date_manager import DateManager\nfrom analysis.engines.indicator_validation_framework import (\n    IndicatorValidationFramework,\n    IndicatorValidationConfig,\n    ValidationMode\n)\nfrom utils.logger import get_logger\n\nlogger = get_logger(__name__)\n\n\nclass TestUnifiedAnalysisEngineIntegration(unittest.TestCase):\n    \"\"\"统一分析引擎集成测试\"\"\"\n    \n    def setUp(self):\n        \"\"\"测试前准备\"\"\"\n        # 创建模拟数据\n        self.mock_data = pd.DataFrame({\n            'date': pd.date_range('2024-01-01', periods=100, freq='D'),\n            'open': [10.0 + i * 0.1 for i in range(100)],\n            'high': [10.5 + i * 0.1 for i in range(100)],\n            'low': [9.5 + i * 0.1 for i in range(100)],\n            'close': [10.2 + i * 0.1 for i in range(100)],\n            'volume': [1000000 + i * 10000 for i in range(100)]\n        })\n        \n        # 初始化各个引擎\n        self.indicator_engine = UnifiedIndicatorEngine()\n        self.condition_evaluator = SharedConditionEvaluator()\n        self.logic_processor = ComplexLogicProcessor()\n        self.date_manager = DateManager()\n        \n        # 模拟数据库\n        self.mock_db = Mock()\n        self.date_manager.db = self.mock_db\n    \n    def test_indicator_engine_integration(self):\n        \"\"\"测试指标引擎集成\"\"\"\n        logger.info(\"测试指标引擎集成\")\n        \n        # 测试核心指标计算\n        indicators = ['MA', 'EMA', 'MACD', 'RSI', 'KDJ']\n        \n        for indicator in indicators:\n            with self.subTest(indicator=indicator):\n                result = self.indicator_engine.calculate_indicator(\n                    indicator, self.mock_data\n                )\n                \n                self.assertIsInstance(result, pd.DataFrame)\n                self.assertGreater(len(result), 0)\n                logger.info(f\"✅ {indicator} 指标计算成功\")\n    \n    def test_condition_evaluator_integration(self):\n        \"\"\"测试条件评估器集成\"\"\"\n        logger.info(\"测试条件评估器集成\")\n        \n        # 测试不同类型的条件\n        test_conditions = [\n            {\n                'type': 'price',\n                'field': 'close',\n                'operator': '>',\n                'value': 15.0\n            },\n            {\n                'type': 'indicator',\n                'indicator_id': 'MA',\n                'period': 5,\n                'operator': '>',\n                'value': 'MA_20'\n            },\n            {\n                'type': 'volume',\n                'field': 'volume',\n                'operator': '>',\n                'value': 1500000\n            }\n        ]\n        \n        for i, condition in enumerate(test_conditions):\n            with self.subTest(condition_index=i):\n                result = self.condition_evaluator.evaluate_condition(\n                    condition, self.mock_data\n                )\n                \n                self.assertIsInstance(result, (bool, pd.Series))\n                logger.info(f\"✅ 条件 {i+1} 评估成功\")\n    \n    def test_logic_processor_integration(self):\n        \"\"\"测试逻辑处理器集成\"\"\"\n        logger.info(\"测试逻辑处理器集成\")\n        \n        # 测试复杂逻辑表达式\n        test_expressions = [\n            \"MA(5) > MA(20)\",\n            \"RSI(14) < 30 AND VOLUME > 1000000\",\n            \"MACD_DIF > MACD_DEA OR KDJ_K > KDJ_D\",\n            \"(CLOSE > OPEN) AND (VOLUME > AVG(VOLUME, 20))\"\n        ]\n        \n        # 设置变量上下文\n        variables = {\n            'CLOSE': 15.5,\n            'OPEN': 15.0,\n            'VOLUME': 1500000\n        }\n        \n        for expr in test_expressions:\n            with self.subTest(expression=expr):\n                try:\n                    result = self.logic_processor.evaluate_expression(\n                        expr, variables\n                    )\n                    self.assertIsInstance(result, (bool, int, float))\n                    logger.info(f\"✅ 表达式 '{expr}' 评估成功: {result}\")\n                except Exception as e:\n                    logger.warning(f\"⚠️ 表达式 '{expr}' 评估失败: {e}\")\n    \n    def test_date_manager_integration(self):\n        \"\"\"测试日期管理器集成\"\"\"\n        logger.info(\"测试日期管理器集成\")\n        \n        # 模拟数据库返回数据\n        mock_df = pd.DataFrame({\n            'latest_date': ['2024-01-15']\n        })\n        self.mock_db.query_df.return_value = mock_df\n        \n        # 测试日期功能\n        test_cases = [\n            ('get_latest_trading_date', {}),\n            ('parse_date', {'date_input': '2024-01-15'}),\n            ('format_date', {'date_input': '2024-01-15'}),\n            ('get_previous_trading_dates', {'base_date': '2024-01-15', 'count': 5}),\n            ('get_next_trading_dates', {'base_date': '2024-01-15', 'count': 5})\n        ]\n        \n        for method_name, kwargs in test_cases:\n            with self.subTest(method=method_name):\n                method = getattr(self.date_manager, method_name)\n                result = method(**kwargs)\n                \n                self.assertIsNotNone(result)\n                logger.info(f\"✅ {method_name} 执行成功\")\n    \n    def test_full_workflow_integration(self):\n        \"\"\"测试完整工作流程集成\"\"\"\n        logger.info(\"测试完整工作流程集成\")\n        \n        # 模拟完整的股票分析工作流程\n        \n        # 1. 日期管理\n        mock_df = pd.DataFrame({'latest_date': ['2024-01-15']})\n        self.mock_db.query_df.return_value = mock_df\n        \n        latest_date = self.date_manager.get_latest_trading_date()\n        self.assertIsInstance(latest_date, str)\n        logger.info(f\"✅ 获取最新交易日期: {latest_date}\")\n        \n        # 2. 指标计算\n        ma_result = self.indicator_engine.calculate_indicator('MA', self.mock_data, period=5)\n        rsi_result = self.indicator_engine.calculate_indicator('RSI', self.mock_data, period=14)\n        \n        self.assertIsInstance(ma_result, pd.DataFrame)\n        self.assertIsInstance(rsi_result, pd.DataFrame)\n        logger.info(\"✅ 技术指标计算完成\")\n        \n        # 3. 条件评估\n        condition = {\n            'type': 'indicator',\n            'indicator_id': 'MA',\n            'period': 5,\n            'operator': '>',\n            'value': 15.0\n        }\n        \n        condition_result = self.condition_evaluator.evaluate_condition(\n            condition, self.mock_data\n        )\n        self.assertIsNotNone(condition_result)\n        logger.info(\"✅ 条件评估完成\")\n        \n        # 4. 复杂逻辑处理\n        expression = \"MA_5 > 15.0 AND RSI_14 < 70\"\n        variables = {\n            'MA_5': 16.0,\n            'RSI_14': 65.0\n        }\n        \n        logic_result = self.logic_processor.evaluate_expression(\n            expression, variables\n        )\n        self.assertIsInstance(logic_result, bool)\n        logger.info(f\"✅ 复杂逻辑处理完成: {logic_result}\")\n        \n        # 5. 性能统计\n        stats = {\n            'indicator_engine': self.indicator_engine.get_performance_stats(),\n            'condition_evaluator': self.condition_evaluator.get_performance_stats(),\n            'logic_processor': self.logic_processor.get_performance_stats(),\n            'date_manager': self.date_manager.get_performance_stats()\n        }\n        \n        for engine_name, engine_stats in stats.items():\n            self.assertIsInstance(engine_stats, dict)\n            logger.info(f\"✅ {engine_name} 性能统计: {engine_stats}\")\n    \n    def test_validation_framework_integration(self):\n        \"\"\"测试验证框架集成\"\"\"\n        logger.info(\"测试验证框架集成\")\n        \n        # 创建验证配置\n        config = IndicatorValidationConfig(\n            mode=ValidationMode.QUICK,\n            stock_pool_size=10,\n            debug_mode=True,\n            stop_on_success=True\n        )\n        \n        # 创建验证框架\n        framework = IndicatorValidationFramework(config)\n        self.assertIsNotNone(framework)\n        logger.info(\"✅ 验证框架创建成功\")\n        \n        # 测试策略生成\n        test_indicators = ['MA', 'MACD', 'RSI']\n        \n        for indicator in test_indicators:\n            with self.subTest(indicator=indicator):\n                strategy = framework._generate_indicator_strategy(indicator)\n                \n                # 验证策略结构\n                required_fields = ['strategy_id', 'name', 'conditions']\n                for field in required_fields:\n                    self.assertIn(field, strategy)\n                \n                self.assertIsInstance(strategy['conditions'], list)\n                self.assertGreater(len(strategy['conditions']), 0)\n                \n                logger.info(f\"✅ {indicator} 策略生成成功\")\n    \n    def test_error_handling_integration(self):\n        \"\"\"测试错误处理集成\"\"\"\n        logger.info(\"测试错误处理集成\")\n        \n        # 测试各引擎的错误处理\n        error_test_cases = [\n            (\n                self.indicator_engine.calculate_indicator,\n                ('INVALID_INDICATOR', self.mock_data),\n                \"指标引擎错误处理\"\n            ),\n            (\n                self.condition_evaluator.evaluate_condition,\n                ({'type': 'invalid', 'field': 'close'}, self.mock_data),\n                \"条件评估器错误处理\"\n            ),\n            (\n                self.logic_processor.evaluate_expression,\n                (\"INVALID_EXPRESSION +++\", {}),\n                \"逻辑处理器错误处理\"\n            ),\n            (\n                self.date_manager.parse_date,\n                (\"invalid_date_string\",),\n                \"日期管理器错误处理\"\n            )\n        ]\n        \n        for method, args, test_name in error_test_cases:\n            with self.subTest(test=test_name):\n                try:\n                    result = method(*args)\n                    # 如果没有抛出异常，检查是否返回了合理的默认值\n                    logger.info(f\"✅ {test_name}: 返回默认值 {result}\")\n                except Exception as e:\n                    # 期望的异常处理\n                    self.assertIsInstance(e, (ValueError, KeyError, Exception))\n                    logger.info(f\"✅ {test_name}: 正确抛出异常 {type(e).__name__}\")\n    \n    def test_performance_integration(self):\n        \"\"\"测试性能集成\"\"\"\n        logger.info(\"测试性能集成\")\n        \n        # 大量数据性能测试\n        large_data = pd.DataFrame({\n            'date': pd.date_range('2020-01-01', periods=1000, freq='D'),\n            'open': [10.0 + i * 0.01 for i in range(1000)],\n            'high': [10.5 + i * 0.01 for i in range(1000)],\n            'low': [9.5 + i * 0.01 for i in range(1000)],\n            'close': [10.2 + i * 0.01 for i in range(1000)],\n            'volume': [1000000 + i * 1000 for i in range(1000)]\n        })\n        \n        start_time = datetime.datetime.now()\n        \n        # 批量指标计算\n        indicators = ['MA', 'EMA', 'RSI', 'MACD']\n        for indicator in indicators:\n            result = self.indicator_engine.calculate_indicator(\n                indicator, large_data\n            )\n            self.assertIsInstance(result, pd.DataFrame)\n        \n        # 批量条件评估\n        conditions = [\n            {'type': 'price', 'field': 'close', 'operator': '>', 'value': 15.0},\n            {'type': 'volume', 'field': 'volume', 'operator': '>', 'value': 1500000}\n        ]\n        \n        for condition in conditions:\n            result = self.condition_evaluator.evaluate_condition(\n                condition, large_data\n            )\n            self.assertIsNotNone(result)\n        \n        end_time = datetime.datetime.now()\n        duration = (end_time - start_time).total_seconds()\n        \n        # 性能要求：处理1000条数据应在5秒内完成\n        self.assertLess(duration, 5.0)\n        logger.info(f\"✅ 性能测试通过: {duration:.2f}秒处理1000条数据\")\n        \n        # 获取性能统计\n        all_stats = {\n            'indicator_engine': self.indicator_engine.get_performance_stats(),\n            'condition_evaluator': self.condition_evaluator.get_performance_stats(),\n            'logic_processor': self.logic_processor.get_performance_stats(),\n            'date_manager': self.date_manager.get_performance_stats()\n        }\n        \n        logger.info(f\"📊 综合性能统计: {all_stats}\")\n\n\nif __name__ == '__main__':\n    unittest.main() 